set nocount on            
select @@fields into #t from d72 a
    @@join
  where @@key order by line

select id_pn, line_pn, sum(a.so_luong*a.he_so) as sl_pn into #sl from d72 a with(index(id_pn)) where exists(select 1 from #t b where a.id_pn = b.id and a.line_pn = b.line) group by id_pn, line_pn
update #t set sl_pn = b.sl_pn from #t a join #sl b on a.id = b.id_pn and a.line = b.line_pn
update #t set so_ct_pn = b.so_ct from #t a join m72 b on a.id_pn = b.id

select * from #t order by line
drop table #t








  &DefaultButton;




function dir$m72(p){
  this.constructor(p);
}
dir$m72.prototype = new DirEvent();
dir$m72.prototype.afterInit = function(renderType){
  var p = this._dir, g = p.grid();
  var exp = {
    tien_nt: ['*tien_nt', '[so_luong]*[he_so]*[gia_nt]'], // Cong thuc tung dong cua GRID
    gia: ['*gia', '[!ty_gia]*[gia_nt]'],
    tien: ['*tien', '[so_luong]*[he_so]*[gia]'],
    tien_tg: ['*tien', '[!ty_gia]*[tien_nt]'],

    t_so_luong: ['@t_so_luong', '[so_luong]'],
    t_tien_nt: ['@t_tien_nt', '[tien_nt]'],
    t_tien: ['@t_tien', '[tien]']
  }
  p.applyExpression(exp, g, false); //Ko can de quy tinh cong thuc

  g.FomulaApplied = {
    "so_luong":["t_so_luong","tien_nt","tien_tg","t_tien_nt","t_tien"],
    "he_so":["tien_nt","tien_tg","t_tien_nt","t_tien"],
    "gia_nt":["tien_nt","gia","tien_tg","t_tien_nt","t_tien"],
    "!ty_gia":["gia", "tien_tg", "t_tien"],
    "tien_nt":["tien_tg","t_tien_nt","t_tien"],
    "gia":["tien","t_tien"],
    "tien":["t_tien"]
  } //Gan lai valid của từng cột sẽ tính các công thức nào theo thứ tự.

  //console.log(JSON.stringify(g.FomulaApplied)); //Gan la ds cong thuc tinh cho cot nao do: 

  p.options.FCColumns = {FC: ['t_tien_nt'], BC: ['t_tien']};
  g.FCColumns = {FC: ['gia_nt', 'tien_nt'], BC: ['gia', 'tien']};

  var oldTG = '', oTG = p.jObject('ma_nt'); //Neu ty gia thay doi
  oTG.focus(function(){ oldTG = oTG.fval(); }).blur(function(){ if (oldTG != oTG.fval()) onExRateChanged(oTG, p);});
  p.applyFCColumns();
  p.applyFCColumns(g);
  p.setFCHidden(oTG.fval());

  dir$m72DisabledMasterField(p, g);
  dir$m72HiddenColumnByType(p);
  dir$m72HiddenColumnByTran(p);
  dir$m72DisabledStatusByAction(p);
}

dir$m72.prototype.beforeButtonDialogClick = function (id) {
  var p = this._dir;
  switch (id) {
    default:
      break;
  }
  return true;
}
dir$m72.prototype.beforeButtonGridClick = function (id, gindex) {
  var p = this._dir;
  switch (id) {
    case '10':
      if (p.valForm('ma_kh') == '') {
        p.jObject('ma_kh').focus(); 
        return;
      }

      if (p.valForm('ma_ngv') != 1) {
        p.jObject('ma_ngv').focus();
        $.showToast(p.msg('physicalRetrieve'));
        return;
      }
      else $.createDir(false, { controller: "m72PN1", folder: "Filter", dirViewType: "Dialog", parent: p, _ngay_ct2: p.valForm('ngay_ct'), _ma_kh: p.valForm('ma_kh'), _ten_kh: p.valForm('ten_kh'), _ma_nt: p.valForm('ma_nt'), _unit_id: p.valForm('unit_id')});
      return false;
      break;
    default:
      break;
  }
  return true;
}

dir$m72.prototype.gridCellValueChange = function (o, g, r, c, v) {
  var p = this._dir;
  switch (c){
    case 'ma_vt':
      p.grequest(g, 'Item', '', ['ma_vt', 'dvt', 'he_so', 'ma_kho', 'ma_lo', 'ma_vi_tri', '!unit_id'], function(pp, d, run) {
        p.calcValidExpression(g, 'he_so', r);
        dir$m72DisabledMasterField(p, g);
      }, r);
      break;
    case 'dvt':
      p.grequest(g, 'UOM', '', ['ma_vt', 'dvt', 'he_so', 'ma_kho', 'ma_lo', 'ma_vi_tri', '!unit_id'], function(pp, d, run) {
        p.calcValidExpression(g, 'he_so', r);
      }, r);
      break;
    case 'ma_kho':
      p.grequest(g, 'Site', '', ['ma_vt', 'dvt', 'he_so', 'ma_kho', 'ma_lo', 'ma_vi_tri', '!unit_id'], function(pp, d, run){
        //Xu ly sau khi valid ma_kho
      }, r);
      break;
    default:
      break;
  }
}
dir$m72.prototype.formFieldValueChange = function (o, cF, v) {
  var p = this._dir;
  switch (cF){
&VoucherExRateValid01;
    case 'ma_gd':
      dir$m72HiddenColumnByTran(p);
      break;
    case 'ma_ngv':
      dir$m72HiddenColumnByType(p);
      break;
    case 'ty_gia':
      p.calcExpressionAll(0, '!ty_gia');
      break;
    default:
      break;
  }
}
function onExRateChanged(o, p) {
  p.setFCHidden(o.fval());
  p.setColumnHidden(0, ['pn_tb', 'gia_nt', 'gia', 'tien_nt', 'tien'], p.valForm('ma_ngv') == 2);
  p.request('GetExRate', '', ['ma_nt', 'ngay_ct'], function(){
    p.calcExpressionAll(0, '!ty_gia');
  });
}
dir$m72.prototype.gridDetailActionChange = function(gindex, action, r){
  var p = this._dir;
  if (action == 'AfterDeleteRow' || action == 'AfterAppendGrid') dir$m72DisabledMasterField(p, p.grid(gindex));
  return true;
}
function dir$m72DisabledMasterField(p, g){
  var dt = g.data, rows = dt.findRow("[ma_vt].trim() != ''"), dis = rows.length > 0;
  p.setDisabled('unit_id', dis);
  p.setInactive('unit_id', true);
  p.setDisabled('ma_ngv', dis);
  rows = dt.findRow("[ma_vt].trim() != '' && [id_pn] > 0"), dis = rows.length > 0;
  p.setDisabled('ma_kh', dis);
}
function dir$m72HiddenColumnByType(p){
  var v = p.valForm('ma_ngv'), nt = p.valForm('ma_nt'), bc = p.options.struct.baseCurrency;
  p.setColumnHidden(0, ['sl_pn'], v == 1 || v == 3);
  p.setColumnHidden(0, ['line_pn', 'so_ct_pn'], v == 2 || v == 3);
  p.setColumnHidden(0, ['pn_tb', 'gia_nt', 'gia', 'tien_nt', 'tien'], v == 2);
  p.setColumnHidden(0, ['gia', 'tien'], v == 2 || nt == bc);
  p.setAuth(['t_tien_nt', 't_tien'], v == 2, true);
  p.setInvisible(['t_tien'], nt == bc);
}
function dir$m72HiddenColumnByTran(p){

}
function dir$m72DisabledStatusByAction(p){
  var o = p.jObject('status');
  if (p.options.action != 'VIEW') o.find("[value=6],[value=7],[value=9]").remove();
}







